insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$araraquara$q$, $q$https://araraquara.siscam.com.br/arquivo?Id=296909 (Lei 10.956/2023, nova redação do art. 1º da Lei 4.420/1994) ; https://araraquara.siscam.com.br/arquivo?Id=106537 (Lei 4.420/1994) ; https://araraquara.siscam.com.br/arquivo?Id=114864 (Dec. 7.208/1997, ARA-080)$q$, $q$Atos oficiais de Araraquara: domínio público (Lei 9.610/1998 art. 8º IV). Geometria das vias: OpenStreetMap (ODbL 1.0, © colaboradores do OSM), casada por nome e trecho.$q$, 63, $q$Regra principal: Lei 4.420/1994 com a redação da Lei 10.956/2023 (12 trechos centrais, dias úteis 10h–19h e sábado 10h–14h; Rua Voluntários da Pátria entre a Av. XV de Novembro e a Av. José Bonifácio sem horário). Exceção: mudanças/transportes residenciais ou comerciais com autorização escrita (Lei 5.322/1999 red. 10.956/2023). A ARA-080 (Dec. 7.208/1997) fica desativada: a Prefeitura anuncia hoje limite de 7 t PBT, sem ato localizado.$q$);
